//! Stat rules from `packages/data/tables/*.toml` and `packages/data/classes/*.toml`
//! (Story E1.2; the files are generated by `packages/data/scripts/gen_tables.py`).
//!
//! Loading is all-or-nothing: every file is parsed, every decimal is parsed exactly (no
//! binary floating point anywhere on this path), every literal is checked against its
//! stored scaled integer, coverage and cross-file references are checked, and the result
//! goes through [`StatRules::new`]. Any problem aborts startup with **every** error listed.
//! [`ResolvedRules::config_hash`] is a SHA-256 over a canonical JSON encoding of the parsed
//! files, so comments and formatting do not change it and any value change does.

use super::exact_decimal::parse_decimal;

use std::collections::BTreeMap;
use std::fmt;
use std::path::Path;

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use crate::application::zone_bootstrap::ResolvedRules;
use crate::domain::zone::{
    Archetype, BonusTable, ClassTemplate, FormulaConstants, Quadratic, Scaled, StatBonusTables,
    StatRules, StatRulesParts, WeaponBlock, BONUS_TABLE_LEN, Q,
};
use crate::domain::{BaseStats, Race};

macro_rules! data_file {
    ($path:literal) => {
        ($path, include_str!(concat!("../../../../packages/data/", $path)))
    };
}

/// The rule files compiled into the binary, so the server starts without a data directory.
pub const EMBEDDED: [(&str, &str); 14] = [
    data_file!("tables/stat_bonus.toml"),
    data_file!("tables/formulas.toml"),
    data_file!("tables/experience.toml"),
    data_file!("tables/penalties.toml"),
    data_file!("tables/starter_weapon.toml"),
    data_file!("classes/dark_fighter.toml"),
    data_file!("classes/dark_mystic.toml"),
    data_file!("classes/dwarven_fighter.toml"),
    data_file!("classes/elven_fighter.toml"),
    data_file!("classes/elven_mystic.toml"),
    data_file!("classes/human_fighter.toml"),
    data_file!("classes/human_mystic.toml"),
    data_file!("classes/orc_fighter.toml"),
    data_file!("classes/orc_mystic.toml"),
];

const TABLES: [&str; 5] = [
    "tables/stat_bonus.toml",
    "tables/formulas.toml",
    "tables/experience.toml",
    "tables/penalties.toml",
    "tables/starter_weapon.toml",
];

/// Rule file contents keyed by path relative to `packages/data` (`tables/…`, `classes/…`).
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct RulesSource(pub BTreeMap<String, String>);

impl RulesSource {
    /// The compiled-in files.
    #[must_use]
    pub fn embedded() -> Self {
        Self(
            EMBEDDED
                .iter()
                .map(|(p, s)| ((*p).to_owned(), (*s).to_owned()))
                .collect(),
        )
    }

    /// Reads the five tables and every `classes/*.toml` under `dir` (a `packages/data`).
    pub fn from_dir(dir: &Path) -> anyhow::Result<Self> {
        use anyhow::Context as _;
        let mut files = BTreeMap::new();
        for rel in TABLES {
            let path = dir.join(rel);
            let src = std::fs::read_to_string(&path)
                .with_context(|| format!("read {}", path.display()))?;
            files.insert(rel.to_owned(), src);
        }
        let classes = dir.join("classes");
        for entry in
            std::fs::read_dir(&classes).with_context(|| format!("read {}", classes.display()))?
        {
            let path = entry?.path();
            if path.extension().is_some_and(|e| e == "toml") {
                let name = path
                    .file_name()
                    .map(|n| n.to_string_lossy().into_owned())
                    .unwrap_or_default();
                let src = std::fs::read_to_string(&path)
                    .with_context(|| format!("read {}", path.display()))?;
                files.insert(format!("classes/{name}"), src);
            }
        }
        Ok(Self(files))
    }
}

/// Every problem found while loading; startup prints them all.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RulesError(pub Vec<String>);

impl fmt::Display for RulesError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(f, "stat rules rejected ({} errors):", self.0.len())?;
        for e in &self.0 {
            writeln!(f, "  - {e}")?;
        }
        Ok(())
    }
}

impl std::error::Error for RulesError {}

// ---------------------------------------------------------------------------
// Exact decimals
// ---------------------------------------------------------------------------

/// Collects errors while converting, so one bad value does not hide the next.
#[derive(Default)]
struct Errors(Vec<String>);

impl Errors {
    fn push(&mut self, msg: String) {
        self.0.push(msg);
    }

    /// Parses `literal` and checks it equals the generator's `stored` scaled integer.
    fn decimal(&mut self, ctx: &str, literal: &str, stored: Option<i64>) -> Scaled {
        match parse_decimal(literal) {
            Ok(v) => {
                if let Some(q) = stored {
                    if q != v.raw() {
                        self.push(format!(
                            "{ctx}: literal {literal} is {} at Q, stored {q}",
                            v.raw()
                        ));
                    }
                }
                v
            },
            Err(e) => {
                self.push(format!("{ctx}: {e}"));
                Scaled::ZERO
            },
        }
    }

    fn require(&mut self, ok: bool, msg: impl FnOnce() -> String) {
        if !ok {
            self.push(msg());
        }
    }
}

