macro_rules! formula {
    ($name:ident { $($field:ident : $ty:ty),* $(,)? }) => {
        #[derive(Debug, Deserialize, Serialize)]
        #[serde(deny_unknown_fields)]
        struct $name {
            file: String,
            symbol: String,
            literal: Vec<String>,
            $($field: $ty,)*
        }
    };
}

